import json, collections, os
os.chdir("/data/p12r3a")
S = ("ADAUSDT", "GRAMUSDT", "STXUSDT")
for m in ("08", "09"):
    for cap in (0, 3):
        a = json.load(open(f"closes-r2bd-cap{cap}-2026-{m}.json")); b = json.load(open(f"closes-r2bf-cap{cap}-2026-{m}.json"))
        v = [k for k in b if "tape60q0.0508963626" in k or "tape60q0.0489634474" in k or "tape15q0.005260825702856262" in k]
        for k in v:
            for mo, cs in b[k].items():
                for c, tr in cs.items():
                    print(m, cap, k[-30:], mo, c, len(tr), round(sum(x[1] for x in tr), 4))
        if cap == 0:
            ex = next(iter(b[v[0]].values())); print("sample", next(iter(ex.values()))[0])
        add = rem = foreign = 0
        for k in set(a) | set(b):
            for mo in set(a.get(k, {})) | set(b.get(k, {})):
                for c in set(a.get(k, {}).get(mo, {})) | set(b.get(k, {}).get(mo, {})):
                    A = collections.Counter(map(json.dumps, a.get(k, {}).get(mo, {}).get(c, [])))
                    B = collections.Counter(map(json.dumps, b.get(k, {}).get(mo, {}).get(c, [])))
                    d = B - A; r = A - B
                    add += sum(d.values()); rem += sum(r.values())
                    foreign += sum(n for x, n in d.items() if not any(s in x for s in S))
        print("cap", cap, m, "added", add, "removed", rem, "added_not_3sym", foreign, "keys", len(a), len(b))
